            wrapper = _cached_wrapper(func, cache, key, _lock, make_info)
        else:
            wrapper = _cached_wrapper(func, cache, key, _lock, None)

        wrapper.cache = cache
        wrapper.cache_key = key
        wrapper.cache_lock = _lock
        wrapper.cache_condition = condition

